<?php
require_once __DIR__.'/config.php'; require_login();
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM blocks WHERE id=?')->execute([(int)$_GET['delete']]);flash('بلوک حذف شد.');redirect('blocks.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)post('id');$data=[(int)post('building_id'),trim(post('name')),trim(post('code'))?:null,(int)post('floor_count',0),(int)post('units_per_floor',0)];if($id){$data[]=$id;$pdo->prepare('UPDATE blocks SET building_id=?,name=?,code=?,floor_count=?,units_per_floor=? WHERE id=?')->execute($data);flash('بلوک ویرایش شد.');}else{$pdo->prepare('INSERT INTO blocks(building_id,name,code,floor_count,units_per_floor) VALUES(?,?,?,?,?)')->execute($data);flash('بلوک اضافه شد.');}redirect('blocks.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM blocks WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$buildings=$pdo->query('SELECT id,name FROM buildings ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT b.*,g.name building_name FROM blocks b JOIN buildings g ON g.id=b.building_id ORDER BY b.id DESC')->fetchAll();page_header('بلوک‌ها');
?><div class="toolbar"><h1>بلوک‌ها</h1><a class="button" href="blocks.php?new=1">+ بلوک جدید</a></div><?php if(isset($_GET['new'])||$edit):?><form class="form" method="post"><?=csrf_field()?><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="grid"><label>ساختمان<select name="building_id" required><?php foreach($buildings as $b):?><option value="<?=$b['id']?>" <?=($edit['building_id']??'')==$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><label>نام بلوک<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>کد<input name="code" value="<?=e($edit['code']??'')?>"></label><label>تعداد طبقات<input type="number" name="floor_count" value="<?=$edit['floor_count']??0?>"></label><label>واحد در هر طبقه<input type="number" name="units_per_floor" value="<?=$edit['units_per_floor']??0?>"></label></div><div class="actions"><button>ذخیره</button><a class="button" href="blocks.php">انصراف</a></div></form><hr><?php endif;?><div class="table-wrap"><table class="table"><tr><th>بلوک</th><th>ساختمان</th><th>طبقات</th><th>واحد/طبقه</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['building_name'])?></td><td><?=$r['floor_count']?></td><td><?=$r['units_per_floor']?></td><td><a class="button" href="blocks.php?edit=<?=$r['id']?>">ویرایش</a> <a class="button danger" onclick="return confirm('حذف شود؟')" href="blocks.php?delete=<?=$r['id']?>">حذف</a></td></tr><?php endforeach;?></table></div><?php page_footer();?>
